<script setup>
import {ref,computed,watch} from 'vue';
import {api} from '../services/accounting.js';
import {useContext} from '../composables/context.js';
import {useAccess} from '../composables/access.js';
const props=defineProps({sourceKind:{type:String,required:true},sourceId:{type:[String,Number],required:true},readOnly:Boolean});
const {company}=useContext(),{can}=useAccess();
const farms=ref([]),groups=ref([]),assignment=ref(null),farmId=ref(''),groupId=ref(''),busy=ref(false),error=ref(''),notice=ref('');let generation=0;
const available=computed(()=>groups.value.filter(group=>String(group.farm_id)===String(farmId.value)));
const path=()=>'/farm-organization/assignments/'+props.sourceKind+'/'+props.sourceId;
watch([()=>company.value?.id,()=>props.sourceKind,()=>props.sourceId],async()=>{const ticket=++generation;error.value='';notice.value='';farms.value=[];groups.value=[];assignment.value=null;farmId.value='';groupId.value='';try{const [catalog,current]=await Promise.all([api('/farm-organization'),api(path())]);if(ticket!==generation)return;farms.value=Array.isArray(catalog.farms)?catalog.farms:[];groups.value=Array.isArray(catalog.groups)?catalog.groups:[];assignment.value=current;farmId.value=current?.farm_id?String(current.farm_id):'';groupId.value=current?.group_id?String(current.group_id):'';}catch(cause){if(ticket===generation)error.value='No s’ha pogut carregar la classificació ('+cause.code+').';}},{immediate:true});
async function save(){if(busy.value)return;const ticket=generation;busy.value=true;error.value='';notice.value='';try{const result=await api(path(),{method:'PUT',body:{farm_id:farmId.value||null,group_id:groupId.value||null,version:assignment.value?.version??null}});if(ticket===generation){assignment.value=result;notice.value='Classificació guardada.';}}catch(cause){if(ticket===generation)error.value=cause.code==='FARM_CHANGED'?'La classificació ha canviat. Torna a obrir la factura.':'No s’ha pogut guardar la classificació ('+cause.code+').';}finally{busy.value=false;}}
</script>
<template><section class="farm-classification"><h3>Organització de la despesa</h3><div class="farm-classification-fields"><label>Granja<select aria-label="Granja" v-model="farmId" :disabled="busy||readOnly||!can('accounting_write')" @change="groupId='';notice='' "><option value="">Sense granja</option><option v-for="farm in farms" :key="farm.id" :value="String(farm.id)">{{ farm.name }}</option></select></label><label>Grup<select aria-label="Grup" v-model="groupId" :disabled="busy||!farmId||readOnly||!can('accounting_write')"><option value="">Sense grup</option><option v-for="group in available" :key="group.id" :value="String(group.id)">{{ group.name }}</option></select></label></div><button v-if="!readOnly&&can('accounting_write')" type="button" class="button" :disabled="busy" @click="save">Guardar classificació</button><p v-if="notice" role="status">{{ notice }}</p><p v-if="error" role="alert" class="notice error-notice">{{ error }}</p><RouterLink to="/granjas">Gestionar granges i grups</RouterLink></section></template>
<style scoped>.farm-classification{margin:20px 0;padding:16px;border:1px solid #dce4ee;border-radius:8px}.farm-classification h3{margin:0 0 12px}.farm-classification-fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}.farm-classification label{display:flex;flex-direction:column;gap:6px}.farm-classification select{width:100%}.farm-classification button{margin:12px 12px 0 0}.farm-classification a{display:inline-block;margin-top:12px}@media(max-width:600px){.farm-classification-fields{grid-template-columns:1fr}}</style>
